sql.if:
AND H.DEPTNO IN (SELECT D.DEPTNO FROM HR_DEPARTMENT D
                  START WITH D.DEPTNO = #{deptNo, jdbcType=VARCHAR}
                CONNECT BY PRIOR D.DEPTNO = D.PARENT_DEPT_NO)

AND (H.EMPID = #{keyword, jdbcType=VARCHAR}
     OR CONVERTTOUNSIGN(UPPER(NVL(H.LOCAL_NAME, A.STU_LOCAL_NAME)))
        LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%')

mapper.select:

  AND T.MAKER_PERSON_ID = #{adminID, jdbcType=VARCHAR}


  AND T.APPLY_FLAG = #{flag, jdbcType=NUMERIC}

ORDER BY DECODE(T.APPLY_FLAG, 1, 0, 2, 1, 2), A.CREATE_DATE DESC, A.APPLY_NO DESC


  AND T.MAKER_LEVEL > 0


  AND T.CONFIRM_FLAG = #{flag, jdbcType=NUMERIC}

ORDER BY DECODE(T.APPLY_FLAG, 2, 0, 1, 1, 2), T.CONFIRM_FLAG, A.CREATE_DATE DESC, A.APPLY_NO DESC


  AND T.MAKER_LEVEL > 0

  AND A.STU_PERSON_ID = #{adminID, jdbcType=VARCHAR}



  AND T.APPLY_FLAG = #{flag, jdbcType=NUMERIC}

ORDER BY DECODE(T.APPLY_FLAG, 1, 1, 2, 2, 3), NVL(H.LOCAL_NAME, A.STU_LOCAL_NAME), T.CONFIRM_FLAG DESC, B.COURSE_NAME_CODE

mapper.update:
UPDATE EDU_TRAIN_MAKER
   SET APPLY_FLAG = #{flag, jdbcType=NUMERIC},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE APPLY_NO = #{applyNo, jdbcType=NUMERIC}
   AND ACTIVITY = 1
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND NVL(CONFIRM_FLAG, 1) = 1
   AND EXISTS (SELECT 1 FROM EDU_TRAIN_MAKER X
                WHERE X.APPLY_NO = #{applyNo, jdbcType=NUMERIC}
                  AND X.MAKER_PERSON_ID = #{adminID, jdbcType=VARCHAR}
                  AND X.ACTIVITY = 1)

UPDATE EDU_TRAIN_MAKER
   SET CONFIRM_FLAG = #{flag, jdbcType=NUMERIC},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE APPLY_NO = #{applyNo, jdbcType=NUMERIC}
   AND ACTIVITY = 1
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.select:
SELECT COUNT(1) FROM EDU_FREE_EMPLOYEE F
 WHERE F.BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND F.EMPID = #{empId, jdbcType=VARCHAR}
   AND F.ACTIVITY = '1'
   AND F.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

   AND F.FLAG = #{flag, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM EDU_FREE_EMPLOYEE
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND EMPID = #{empId, jdbcType=VARCHAR}
   AND ACTIVITY = '1'
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND FLAG = #{flag, jdbcType=VARCHAR}

DELETE FROM EDU_TRAIN_RESULT
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND STU_EMPID = #{empId, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

DELETE FROM EDU_TEACHER_CHECK
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND STU_EMPID = #{empId, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.select:
SELECT COUNT(1) FROM EDU_STUDENT_APPLY A
 WHERE A.APPLY_NO = #{applyNo, jdbcType=NUMERIC}
   AND A.ACTIVITY = 1
   AND A.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

   AND A.STU_PERSON_ID = #{adminID, jdbcType=VARCHAR}

   AND NOT EXISTS (SELECT 1 FROM EDU_TRAIN_MAKER T
                    WHERE T.APPLY_NO = A.APPLY_NO
                      AND T.ACTIVITY = 1
                      AND (NVL(T.APPLY_FLAG, 1) <> 1 OR NVL(T.CONFIRM_FLAG, 1) <> 1))
